 const dU=det(U);fail((dU<0n?-dU:dU)===13n**21n,"U determinant");
 const adj=Array.from({length:12},(_,i)=>Array.from({length:12},(_,j)=>((i+j)%2?-1n:1n)*det(U.filter((_,k)=>k!==j).map(r=>r.filter((_,k)=>k!==i)))));
