 const normWitness=(w)=>({pos:w.pos,neg:w.neg,z:w.z,u:w.u,residues:w.residues,norm_sq:w.norm_sq,radius_sq:w.radius_sq,masses:w.masses,budget_valid:w.budget_valid});
