    let replace=A=>{let R=A.map(a=>a.slice()),j=R.findIndex(a=>a[0]===q&&a[1]===t0);fail(j>=0,"shared atom exists");R[j]=[q,t];return sort(R)};
    let P=replace(w.pos),N=replace(w.neg),o=observe(P,N,w.u);
