 }
 function witness(w,pp,np){
  const P=w.pos,N=w.neg,u=w.u;
  fail(same(P.map(a=>a[0]),pp)&&same(N.map(a=>a[0]),np)&&same(P,sort(P))&&same(N,sort(N)),"witness roster");
  fail([...P,...N].every(a=>Number.isInteger(a[1])&&a[1]>=1&&a[1]<=12),"label");
